package com.blastmineimproved;

import org.junit.Test;

import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

public class HelperPolicyTest
{
	@Test
	public void dynamiteZeroAndOneLoadedPotIsLight()
	{
		assertTrue(HelperPolicy.canLightLoadedPots(0, 1, 0));
		assertTrue(HelperPolicy.canLightLoadedPots(0, 2, 0));
		assertTrue(HelperPolicy.canLightLoadedPots(0, 1, 1));
	}

	@Test
	public void dynamiteLeftDoesNotLightUnpairedPot()
	{
		assertFalse(HelperPolicy.canLightLoadedPots(1, 1, 0));
		assertTrue(HelperPolicy.canLightLoadedPots(1, 2, 0));
		assertTrue(HelperPolicy.canLightLoadedPots(1, 1, 1));
	}

	@Test
	public void guidePickupOffNeverEmitsCollectAtPair()
	{
		assertFalse(HelperPolicy.emitCollectAtPair(RotationMethod.LOOT_AS_YOU_GO, false));
		assertFalse(HelperPolicy.emitCollectAtPair(RotationMethod.BLAST_THEN_LOOT, false));
		assertFalse(HelperPolicy.emitCollectAtPair(RotationMethod.BLAST_THEN_LOOT, true));
	}

	@Test
	public void lootAsYouGoGuidesPickupWhenEnabled()
	{
		assertTrue(HelperPolicy.emitCollectAtPair(RotationMethod.LOOT_AS_YOU_GO, true));
	}

	@Test
	public void blastThenLootDoesNotWaitOnGroundOreToReset()
	{
		assertFalse(HelperPolicy.tripResetRequiresClearGround(false));
		assertTrue(HelperPolicy.tripResetRequiresClearGround(true));
	}

	@Test
	public void dynamiteZeroNeverRemovesLight()
	{
		assertTrue(HelperPolicy.neverRemoveLight(0));
		assertFalse(HelperPolicy.neverRemoveLight(1));
	}

	@Test
	public void collectOreHidesIconsButDoesNotStripRockMenus()
	{
		HelperAction.Kind collect = HelperAction.Kind.COLLECT_ORE;
		assertTrue(collect.hidesOffPathIcons());
		assertFalse(collect.iconsOnFocusOnly());
		assertFalse(collect.stripsOffPathRockMenus());
		assertTrue(collect.matchesPrefer("Take"));
		assertTrue(collect.matchesPrefer("Pick-up"));
	}

	@Test
	public void blastingStepsStripOffPathMenus()
	{
		assertTrue(HelperAction.Kind.EXCAVATE.stripsOffPathRockMenus());
		assertTrue(HelperAction.Kind.PLACE_DYNAMITE.stripsOffPathRockMenus());
		assertTrue(HelperAction.Kind.LIGHT.stripsOffPathRockMenus());
		assertFalse(HelperAction.Kind.DEPOSIT_SACK.stripsOffPathRockMenus());
		assertFalse(HelperAction.Kind.BANK_DYNAMITE.stripsOffPathRockMenus());
		assertFalse(HelperAction.Kind.PREP_INVENTORY.stripsOffPathRockMenus());
	}
}

package com.blastmineimproved.overlay;

import com.blastmineimproved.BlastMineImprovedConfig;
import com.blastmineimproved.BlastedOreTracker;
import java.awt.Color;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.time.Duration;
import javax.inject.Inject;
import net.runelite.api.widgets.WidgetItem;
import net.runelite.client.ui.overlay.WidgetItemOverlay;
import net.runelite.client.ui.overlay.components.ProgressPieComponent;
import net.runelite.api.gameval.ItemID;

public class InventoryOreTimerOverlay extends WidgetItemOverlay
{
	private final BlastMineImprovedConfig config;
	private final BlastedOreTracker oreTracker;

	@Inject
	private InventoryOreTimerOverlay(BlastMineImprovedConfig config, BlastedOreTracker oreTracker)
	{
		this.config = config;
		this.oreTracker = oreTracker;
		showOnInventory();
	}

	@Override
	public void renderItemOverlay(Graphics2D graphics, int itemId, WidgetItem widgetItem)
	{
		if (!config.showInventoryOreTimers() || itemId != ItemID.LOVAKENGJ_BLASTED_ORE)
		{
			return;
		}

		BlastedOreTracker.OreTimer matched = oreTracker.timerForSlot(widgetItem.getWidget().getIndex());
		if (matched == null)
		{
			return;
		}

		Duration remaining = matched.remaining();
		Rectangle bounds = widgetItem.getCanvasBounds();
		ProgressPieComponent pie = new ProgressPieComponent();
		pie.setPosition(new net.runelite.api.Point(bounds.x + bounds.width / 2, bounds.y + bounds.height / 2));
		pie.setProgress(matched.remainingRelative());

		Color color = remaining.compareTo(Duration.ofSeconds(45)) < 0
			? Color.RED
			: remaining.compareTo(Duration.ofSeconds(90)) < 0
			? Color.ORANGE
			: Color.CYAN;
		pie.setFill(color);
		pie.setBorderColor(color);
		pie.render(graphics);
	}
}

package com.blastmineimproved.overlay;

import com.blastmineimproved.BlastMineImprovedConfig;
import com.blastmineimproved.BlastMineImprovedPlugin;
import com.blastmineimproved.HelperAction;
import com.blastmineimproved.HelperService;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Point;
import java.awt.Rectangle;
import java.awt.image.BufferedImage;
import java.util.Arrays;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.MenuAction;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.ItemID;
import net.runelite.api.gameval.VarbitID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.game.ItemManager;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.overlay.OverlayPanel;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.components.LayoutableRenderableEntity;
import net.runelite.client.ui.overlay.components.LineComponent;

import static net.runelite.client.ui.overlay.OverlayManager.OPTION_CONFIGURE;

/**
 * The Status Panel: a single movable OverlayPanel showing helper guidance, then the live
 * ore-sack contents. Hides entirely when there's nothing actionable to show.
 */
public class StatusOverlay extends OverlayPanel
{
	private static final int LINE_GAP = 2;
	private static final int ICON_GAP = 2;
	private static final Color DEFAULT_ACTION_COLOR = Color.CYAN;
	private static final Color LABEL_COLOR = Color.WHITE;
	private static final Color DETAIL_COLOR = new Color(170, 170, 170);
	private static final Color XP_COLOR = new Color(140, 220, 140);
	private static final int[] ORE_ITEM_IDS = {
		ItemID.COAL,
		ItemID.GOLD_ORE,
		ItemID.MITHRIL_ORE,
		ItemID.ADAMANTITE_ORE,
		ItemID.RUNITE_ORE
	};
	private static final int[] ORE_VARBITS = {
		VarbitID.LOVAKENGJ_ORE_COAL_BIGGER,
		VarbitID.LOVAKENGJ_ORE_GOLD_BIGGER,
		VarbitID.LOVAKENGJ_ORE_MITHRIL_BIGGER,
		VarbitID.LOVAKENGJ_ORE_ADAMANTITE_BIGGER,
		VarbitID.LOVAKENGJ_ORE_RUNITE_BIGGER
	};

	private final Client client;
	private final BlastMineImprovedConfig config;
	private final HelperService helperService;
	private final ItemManager itemManager;

	private final int[] cachedOreQty = new int[ORE_ITEM_IDS.length];
	private final BufferedImage[] cachedOreIcons = new BufferedImage[ORE_ITEM_IDS.length];

	@Inject
	private StatusOverlay(
		BlastMineImprovedPlugin plugin,
		Client client,
		BlastMineImprovedConfig config,
		HelperService helperService,
		ItemManager itemManager)
	{
		super(plugin);
		setPosition(OverlayPosition.TOP_LEFT);
		setPriority(PRIORITY_MED);
		panelComponent.setGap(new Point(0, LINE_GAP));
		this.client = client;
		this.config = config;
		this.helperService = helperService;
		this.itemManager = itemManager;
		Arrays.fill(cachedOreQty, Integer.MIN_VALUE);
		addMenuEntry(MenuAction.RUNELITE_OVERLAY_CONFIG, OPTION_CONFIGURE, "Jam's Blast Mine");
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		final Widget blastMineWidget = client.getWidget(InterfaceID.LovakengjBlastMiningHud.DATA);
		final boolean hudPresent = blastMineWidget != null;
		final boolean showOre = config.showOreOverlay() && hudPresent;
		// Re-apply every frame: the client recreates/unhides this HUD when entering the
		// mine or enabling the plugin, so a one-shot setHidden is not enough.
		if (hudPresent)
		{
			blastMineWidget.setHidden(config.showOreOverlay());
		}

		HelperAction action = helperService.getCurrentAction();
		boolean showHelper = config.enableHelper()
			&& config.showHelperPanel()
			&& action != null
			&& !(action.getKind() == HelperAction.Kind.IDLE && "Waiting…".equals(action.getDetail()));

		if (!showHelper && !showOre)
		{
			return null;
		}

		panelComponent.getChildren().clear();

		if (showHelper)
		{
			Color actionColor = action.getColor() != null ? action.getColor() : DEFAULT_ACTION_COLOR;
			panelComponent.getChildren().add(LineComponent.builder()
				.left(action.getKind().getLabel())
				.leftColor(actionColor)
				.build());

			panelComponent.getChildren().add(LineComponent.builder()
				.left(action.getDetail())
				.leftColor(DETAIL_COLOR)
				.leftFont(FontManager.getRunescapeSmallFont())
				.build());
		}

		if (showOre)
		{
			if (showHelper)
			{
				panelComponent.getChildren().add(LineComponent.builder().left("").build());
			}

			panelComponent.getChildren().add(new OreIconRow(refreshOreIcons()));

			boolean sackFull = helperService.isCachedSackFull();
			int totalOres = helperService.getCachedTotalSackOres();
			String xp = formatXp(helperService.getCachedSackXp()) + (config.requireProspectors() ? "*" : "");

			if (sackFull)
			{
				panelComponent.getChildren().add(LineComponent.builder()
					.left(totalOres + " ores · " + xp + " · FULL")
					.leftColor(config.getWarningColor())
					.build());
			}
			else
			{
				panelComponent.getChildren().add(LineComponent.builder()
					.left(totalOres + " ores")
					.leftColor(LABEL_COLOR)
					.right(xp)
					.rightColor(XP_COLOR)
					.build());
			}
		}

		return super.render(graphics);
	}

	/** A row of ore icons, laid out as a single panel line. */
	private static final class OreIconRow implements LayoutableRenderableEntity
	{
		private final BufferedImage[] icons;
		private final Rectangle bounds = new Rectangle();
		private Point preferredLocation = new Point(0, 0);

		private OreIconRow(BufferedImage[] icons)
		{
			this.icons = icons;
		}

		@Override
		public Dimension render(Graphics2D graphics)
		{
			int startX = preferredLocation.x;
			int x = startX;
			int height = 0;
			for (BufferedImage icon : icons)
			{
				graphics.drawImage(icon, x, preferredLocation.y, null);
				x += icon.getWidth() + ICON_GAP;
				height = Math.max(height, icon.getHeight());
			}
			Dimension dimension = new Dimension(Math.max(0, x - startX - ICON_GAP), height);
			bounds.setLocation(preferredLocation);
			bounds.setSize(dimension);
			return dimension;
		}

		@Override
		public Rectangle getBounds()
		{
			return bounds;
		}

		@Override
		public void setPreferredLocation(Point preferredLocation)
		{
			this.preferredLocation = preferredLocation;
		}

		@Override
		public void setPreferredSize(Dimension preferredSize)
		{
			// fixed-size row of live item sprites; external sizing requests are ignored
		}
	}

	/** Only rebuild ore images when sack quantities change. */
	private BufferedImage[] refreshOreIcons()
	{
		for (int i = 0; i < ORE_VARBITS.length; i++)
		{
			int qty = client.getVarbitValue(ORE_VARBITS[i]);
			if (qty != cachedOreQty[i] || cachedOreIcons[i] == null)
			{
				cachedOreQty[i] = qty;
				cachedOreIcons[i] = itemManager.getImage(ORE_ITEM_IDS[i], qty, true);
			}
		}
		return cachedOreIcons;
	}

	private static String formatXp(int xp)
	{
		if (xp >= 100_000)
		{
			return String.format("%.0fk XP", xp / 1000.0);
		}
		if (xp >= 10_000)
		{
			return String.format("%.1fk XP", xp / 1000.0);
		}
		return String.format("%,d XP", xp);
	}
}

package com.blastmineimproved.overlay;

import com.blastmineimproved.BlastMineImprovedConfig;
import com.blastmineimproved.HelperAction;
import com.blastmineimproved.HelperService;
import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Polygon;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.Perspective;
import net.runelite.api.coords.LocalPoint;
import net.runelite.api.coords.WorldPoint;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.OverlayUtil;

public class NextClickOverlay extends Overlay
{
	private final Client client;
	private final BlastMineImprovedConfig config;
	private final HelperService helperService;

	@Inject
	private NextClickOverlay(Client client, BlastMineImprovedConfig config, HelperService helperService)
	{
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_SCENE);
		this.client = client;
		this.config = config;
		this.helperService = helperService;
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		if (!config.enableHelper() || !config.highlightNextClick())
		{
			return null;
		}

		HelperAction action = helperService.getCurrentAction();
		if (action == null || action.getHighlightTiles() == null || action.getHighlightTiles().isEmpty())
		{
			return null;
		}

		Color color = action.getColor() != null ? action.getColor() : Color.CYAN;
		for (WorldPoint tile : action.getHighlightTiles())
		{
			LocalPoint local = LocalPoint.fromWorld(client, tile);
			if (local == null)
			{
				continue;
			}

			Polygon poly = Perspective.getCanvasTilePoly(client, local);
			if (poly != null)
			{
				OverlayUtil.renderPolygon(graphics, poly, color);
				graphics.setStroke(new BasicStroke(2));
			}
		}

		return null;
	}
}

package com.blastmineimproved.overlay;

import com.blastmineimproved.BlastMineImprovedConfig;
import com.blastmineimproved.BlastMineImprovedPlugin;
import com.blastmineimproved.BlastMineRock;
import com.blastmineimproved.HelperService;
import com.google.common.collect.ImmutableSet;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Polygon;
import java.awt.image.BufferedImage;
import java.util.Map;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.GameObject;
import net.runelite.api.Perspective;
import net.runelite.api.Point;
import net.runelite.api.Tile;
import net.runelite.api.coords.LocalPoint;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.gameval.ItemID;
import net.runelite.api.gameval.ObjectID;
import net.runelite.client.game.ItemManager;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.components.ProgressPieComponent;
import net.runelite.client.util.ColorUtil;

public class RockOverlay extends Overlay
{
	private static final int MAX_DISTANCE = 16;
	private static final int WARNING_DISTANCE = 1;
	private static final ImmutableSet<Integer> WALL_OBJECTS = ImmutableSet.of(
		ObjectID.BLAST_MINING_WALL_TYPE_TWO, ObjectID.BLAST_MINING_WALL_TYPE_THREE, ObjectID.BLAST_MINING_WALL_TYPE_FIVE,
		ObjectID.BLAST_MINING_ROOF_START_01, ObjectID.BLAST_MINING_ROOF_START_02,
		ObjectID.BLAST_MINING_ROOF_FOR_TYPE_2_01, ObjectID.BLAST_MINING_ROOF_FOR_TYPE_2_02, ObjectID.BLAST_MINING_ROOF_FOR_TYPE_2_03,
		ObjectID.BLAST_MINING_ROOF_FOR_TYPE_3_01,
		ObjectID.BLAST_MINING_WALL_01, ObjectID.BLAST_MINING_WALL_02,
		ObjectID.BLAST_MINING_WALL_CHISELED_01, ObjectID.BLAST_MINING_WALL_CHISELED_02,
		ObjectID.BLAST_MINING_WALL_POT_01, ObjectID.BLAST_MINING_WALL_POT_02,
		ObjectID.BLAST_MINING_WALL_BURNING_01, ObjectID.BLAST_MINING_WALL_BURNING_02,
		ObjectID.BLAST_MINING_WALL_DESTROYED_01, ObjectID.BLAST_MINING_WALL_DESTROYED_02);

	private final Client client;
	private final BlastMineImprovedPlugin plugin;
	private final BlastMineImprovedConfig config;
	private final HelperService helperService;
	private final BufferedImage chiselIcon;
	private final BufferedImage dynamiteIcon;
	private final BufferedImage tinderboxIcon;
	private final ProgressPieComponent fusePie = new ProgressPieComponent();

	@Inject
	private RockOverlay(
		Client client,
		BlastMineImprovedPlugin plugin,
		BlastMineImprovedConfig config,
		HelperService helperService,
		ItemManager itemManager)
	{
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_SCENE);
		this.client = client;
		this.plugin = plugin;
		this.config = config;
		this.helperService = helperService;
		chiselIcon = itemManager.getImage(ItemID.CHISEL);
		dynamiteIcon = itemManager.getImage(ItemID.LOVAKENGJ_DYNAMITE_FUSED);
		tinderboxIcon = itemManager.getImage(ItemID.TINDERBOX);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		Map<WorldPoint, BlastMineRock> rocks = plugin.getRocks();
		if (rocks.isEmpty() || client.getLocalPlayer() == null)
		{
			return null;
		}

		final WorldPoint playerTile = client.getLocalPlayer().getWorldLocation();
		final Tile[][][] tiles = client.getScene().getTiles();

		// Resolve icon policy once per frame — no per-rock config/service thrash.
		final boolean helperIconFilter = config.enableHelper() && config.helperIconsOnly()
			&& helperService.shouldHideOffPathRockIcons();
		final boolean iconsOnFocusOnly = helperIconFilter && helperService.restrictRockIconsToFocusTiles();
		final boolean drawActionIcons = config.showRockIconOverlay();
		final boolean drawTimers = config.showTimerOverlay();
		final boolean drawWarnings = config.showWarningOverlay();

		for (final BlastMineRock rock : rocks.values())
		{
			WorldPoint rockTile = rock.getGameObject().getWorldLocation();
			if (rock.getGameObject().getCanvasLocation() == null
				|| rockTile.distanceTo(playerTile) > MAX_DISTANCE)
			{
				continue;
			}

			switch (rock.getType())
			{
				case NORMAL:
					if (drawActionIcons && shouldDrawActionIcon(helperIconFilter, iconsOnFocusOnly, rockTile))
					{
						drawIconOnRock(graphics, rock, chiselIcon);
					}
					break;
				case CHISELED:
					if (drawActionIcons && shouldDrawActionIcon(helperIconFilter, iconsOnFocusOnly, rockTile))
					{
						drawIconOnRock(graphics, rock, dynamiteIcon);
					}
					break;
				case LOADED:
					if (drawActionIcons && shouldDrawActionIcon(helperIconFilter, iconsOnFocusOnly, rockTile))
					{
						drawIconOnRock(graphics, rock, tinderboxIcon);
					}
					break;
				case LIT:
					if (drawTimers)
					{
						drawTimerOnRock(graphics, rock, config.getTimerColor());
					}
					if (drawWarnings)
					{
						drawAreaWarning(graphics, rock, config.getWarningColor(), tiles);
					}
					break;
				default:
					break;
			}
		}

		return null;
	}

	/**
	 * Deposit/bank/prep: hide all action icons. Excavate/place/light: only focus tiles.
	 * Skipping draws is cheap; we never allocate or toggle overlay registration per icon.
	 */
	private boolean shouldDrawActionIcon(boolean helperIconFilter, boolean iconsOnFocusOnly, WorldPoint rockTile)
	{
		if (!helperIconFilter)
		{
			return true;
		}
		if (!iconsOnFocusOnly)
		{
			return false;
		}
		return helperService.isFocusTile(rockTile);
	}

	private void drawIconOnRock(Graphics2D graphics, BlastMineRock rock, BufferedImage icon)
	{
		Point loc = Perspective.getCanvasImageLocation(client, rock.getGameObject().getLocalLocation(), icon, 150);
		if (loc != null)
		{
			graphics.drawImage(icon, loc.getX(), loc.getY(), null);
		}
	}

	private void drawTimerOnRock(Graphics2D graphics, BlastMineRock rock, Color color)
	{
		Point loc = Perspective.localToCanvas(client, rock.getGameObject().getLocalLocation(), rock.getGameObject().getPlane(), 150);
		if (loc != null)
		{
			final double timeLeft = 1 - rock.getRemainingFuseTimeRelative();
			fusePie.setFill(color);
			fusePie.setBorderColor(color);
			fusePie.setPosition(loc);
			fusePie.setProgress(timeLeft);
			fusePie.render(graphics);
		}
	}

	private void drawAreaWarning(Graphics2D graphics, BlastMineRock rock, Color color, Tile[][][] tiles)
	{
		final int z = client.getPlane();
		int x = rock.getGameObject().getLocalLocation().getX() / Perspective.LOCAL_TILE_SIZE;
		int y = rock.getGameObject().getLocalLocation().getY() / Perspective.LOCAL_TILE_SIZE;

		if (tiles[z][x][y] == null || tiles[z][x][y].getWallObject() == null)
		{
			return;
		}

		final int orientation = tiles[z][x][y].getWallObject().getOrientationA();

		switch (orientation)
		{
			case 1:
				x--;
				break;
			case 4:
				x++;
				break;
			case 8:
				y--;
				break;
			default:
				y++;
		}

		for (int i = -WARNING_DISTANCE; i <= WARNING_DISTANCE; i++)
		{
			for (int j = -WARNING_DISTANCE; j <= WARNING_DISTANCE; j++)
			{
				if (x + i < 0 || y + j < 0 || x + i >= tiles[z].length || y + j >= tiles[z][x + i].length)
				{
					continue;
				}

				final GameObject gameObject = tiles[z][x + i][y + j].getGameObjects()[0];
				if (gameObject == null || !WALL_OBJECTS.contains(gameObject.getId()))
				{
					final LocalPoint localTile = new LocalPoint(
						(x + i) * Perspective.LOCAL_TILE_SIZE + Perspective.LOCAL_TILE_SIZE / 2,
						(y + j) * Perspective.LOCAL_TILE_SIZE + Perspective.LOCAL_TILE_SIZE / 2);
					final Polygon poly = Perspective.getCanvasTilePoly(client, localTile);
					if (poly != null)
					{
						graphics.setColor(ColorUtil.colorWithAlpha(color, (int) (color.getAlpha() / 2.5)));
						graphics.fillPolygon(poly);
					}
				}
			}
		}
	}
}

package com.blastmineimproved;

/**
 * Decision helpers shared by {@link HelperService}, {@link MenuSafetyService}, and unit tests.
 * Kept free of {@code Client} so the 20-vs-21 and pickup-off cases stay testable.
 */
final class HelperPolicy
{
	private HelperPolicy()
	{
	}

	/**
	 * Light when both pots are loaded, the partner is already lit, or dynamite is gone
	 * (odd last pot — do not wait for a partner that cannot be loaded).
	 */
	static boolean canLightLoadedPots(int dynamite, int loaded, int lit)
	{
		if (loaded <= 0)
		{
			return false;
		}
		if (loaded >= 2 || lit > 0)
		{
			return true;
		}
		return dynamite == 0;
	}

	/** Mid-lap pickup is loot-as-you-go only, and only when the user wants the helper to loot. */
	static boolean emitCollectAtPair(RotationMethod method, boolean guideOrePickup)
	{
		return guideOrePickup && method == RotationMethod.LOOT_AS_YOU_GO;
	}

	static boolean tripResetRequiresClearGround(boolean guideOrePickup)
	{
		return guideOrePickup;
	}

	/** A loaded pot is always meant to be fired; never strip Light when dynamite is 0. */
	static boolean neverRemoveLight(int dynamite)
	{
		return dynamite == 0;
	}
}

package com.blastmineimproved;

import java.awt.Color;
import java.util.ArrayList;
import java.util.Collections;
import java.util.EnumMap;
import java.util.EnumSet;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.Getter;
import net.runelite.api.Client;
import net.runelite.api.EquipmentInventorySlot;
import net.runelite.api.Item;
import net.runelite.api.ItemComposition;
import net.runelite.api.ItemContainer;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.gameval.InventoryID;
import net.runelite.api.gameval.ItemID;
import net.runelite.api.gameval.VarbitID;

@Singleton
public class HelperService
{
	private static final int SACK_FULL_THRESHOLD = 900;
	/** Player is "at" the NE rotation when within this distance of any NE marker. */
	private static final int NE_AREA_RADIUS = 10;
	private static final int INVENTORY_SIZE = 28;
	private static final Color NEXT_COLOR = new Color(0, 200, 255, 180);
	private static final Color WARN_COLOR = new Color(255, 170, 0, 180);
	private static final Color DEPOSIT_COLOR = new Color(10, 255, 0, 180);
	private static final Color GUIDE_COLOR = new Color(255, 220, 0, 200);
	/** Prospector kit: helmet, jacket, legs, boots — no gloves. Golden recolor mixes freely with normal pieces for the set bonus. */
	private static final int[] PROSPECTOR_HELMS = {ItemID.MOTHERLODE_REWARD_HAT, ItemID.MOTHERLODE_REWARD_HAT_GOLD};
	private static final int[] PROSPECTOR_BODIES = {ItemID.MOTHERLODE_REWARD_TOP, ItemID.MOTHERLODE_REWARD_TOP_GOLD};
	private static final int[] PROSPECTOR_LEGS = {ItemID.MOTHERLODE_REWARD_LEGS, ItemID.MOTHERLODE_REWARD_LEGS_GOLD};
	private static final int[] PROSPECTOR_BOOTS = {ItemID.MOTHERLODE_REWARD_BOOTS, ItemID.MOTHERLODE_REWARD_BOOTS_GOLD};

	private final Client client;
	private final BlastMineImprovedConfig config;
	private final BlastedOreTracker oreTracker;
	private final GroundOreTracker groundOreTracker;

	@Getter
	private HelperAction currentAction = HelperAction.idle();

	/** Cached highlight tiles for O(1) focus checks in overlays (updated only when action changes). */
	private Set<WorldPoint> focusTiles = Collections.emptySet();

	/**
	 * Loot-as-you-go only: after the planned full laps, guide the short finale pairs.
	 * Blast-then-loot never uses this — it keeps cycling 1-2→7-8 until dynamite is gone.
	 */
	private boolean shortFinale;

	private int fullPassesCompleted;

	/** Sites blasted at least once this trip (eligible for pickup on a later loot-as-you-go pass). */
	private final Set<NortheastSite> blastedThisTrip = EnumSet.noneOf(NortheastSite.class);

	/** Sites already fired this pass — keep moving; don't rework or wait on them. */
	private final Set<NortheastSite> completedThisPass = EnumSet.noneOf(NortheastSite.class);

	/**
	 * Sites that needed excavate/place/load work this pass. Required before LIT can count as
	 * completed — otherwise leftover fuses from the previous lap auto-skip 7-8.
	 */
	private final Set<NortheastSite> workedThisPass = EnumSet.noneOf(NortheastSite.class);

	/** Set when a blast-then-loot trip spends its last dynamite, so the next refill starts a clean lap. */
	private boolean tripExhausted;

	@Getter
	private int cachedSackXp;
	@Getter
	private int cachedTotalSackOres;
	@Getter
	private boolean cachedSackFull;

	@Inject
	HelperService(
		Client client,
		BlastMineImprovedConfig config,
		BlastedOreTracker oreTracker,
		GroundOreTracker groundOreTracker)
	{
		this.client = client;
		this.config = config;
		this.oreTracker = oreTracker;
		this.groundOreTracker = groundOreTracker;
	}

	public void resetRotation()
	{
		shortFinale = false;
		fullPassesCompleted = 0;
		blastedThisTrip.clear();
		completedThisPass.clear();
		workedThisPass.clear();
		tripExhausted = false;
		setCurrentAction(HelperAction.idle());
	}

	public boolean isNearNortheast()
	{
		if (client.getLocalPlayer() == null)
		{
			return false;
		}
		WorldPoint player = client.getLocalPlayer().getWorldLocation();
		for (NortheastSite site : NortheastSite.ORDER)
		{
			if (player.distanceTo(site.getTile()) <= NE_AREA_RADIUS)
			{
				return true;
			}
		}
		return false;
	}

	/** True when this tile is a current helper target. */
	public boolean isFocusTile(WorldPoint point)
	{
		return point != null && focusTiles.contains(point);
	}

	/**
	 * Hide chisel/dynamite/tinderbox icons that are not on the current helper path
	 * (includes deposit/bank/prep — those steps hide all rock action icons).
	 */
	public boolean shouldHideOffPathRockIcons()
	{
		return currentAction != null && currentAction.getKind().hidesOffPathIcons();
	}

	/**
	 * When true with {@link #shouldHideOffPathRockIcons()}, only draw rock action icons on focus
	 * tiles. When false, suppress all rock action icons for this step (deposit/bank/etc.).
	 */
	public boolean restrictRockIconsToFocusTiles()
	{
		return currentAction != null && currentAction.getKind().iconsOnFocusOnly();
	}

	/**
	 * True when off-path excavate/place/light menus should be removed.
	 * Collect/deposit/bank do not share this — they hide icons but must not strip Light.
	 */
	public boolean isFocusingBlastingStep()
	{
		return currentAction != null && currentAction.getKind().stripsOffPathRockMenus();
	}

	public void update(Map<WorldPoint, BlastMineRock> rocks)
	{
		refreshSackCache();

		if (!config.enableHelper() || !BlastMineArea.isInBlastMine(client))
		{
			setCurrentAction(HelperAction.idle());
			return;
		}

		InventorySnapshot inv = scanInventory();
		int oreCount = oreTracker.getOreCount();
		int dynamite = inv.getUnnotedDynamite();
		TripPlan plan = TripPlan.of(config.dynamitePerTrip());
		boolean blastThenLoot = config.rotationMethod() == RotationMethod.BLAST_THEN_LOOT;
		boolean guidePickup = config.guideOrePickup();
		boolean groundClear = !groundOreTracker.hasAnyOre();
		boolean groundOkForReset = !HelperPolicy.tripResetRequiresClearGround(guidePickup) || groundClear;

		if (blastThenLoot)
		{
			if (tripExhausted && dynamite > 0)
			{
				resetRotation();
			}
		}
		else if (shortFinale && oreCount == 0 && dynamite > 0 && groundOkForReset)
		{
			resetRotation();
		}

		if (!isNearNortheast())
		{
			setCurrentAction(new HelperAction(
				HelperAction.Kind.IDLE,
				"Head to the north-east pairs (start at 1-2)",
				List.of(NortheastSite.PAIR_1_2.getTile()),
				GUIDE_COLOR));
			return;
		}

		List<NortheastSite> sites = activeSites(plan, blastThenLoot);
		Map<NortheastSite, List<BlastMineRock>> bySite = groupBySite(rocks);
		updatePassProgress(sites, bySite, plan, blastThenLoot);

		if (cachedSackFull)
		{
			if (needsProspectorKit())
			{
				setCurrentAction(new HelperAction(
					HelperAction.Kind.WEAR_PROSPECTORS,
					"Sack full — wear prospectors, then collect",
					List.of(NortheastSite.OPERATOR),
					WARN_COLOR));
			}
			else
			{
				setCurrentAction(new HelperAction(
					HelperAction.Kind.COLLECT_OPERATOR,
					"Sack full — collect from the operator",
					List.of(NortheastSite.OPERATOR),
					WARN_COLOR));
			}
			return;
		}

		if (oreCount >= plan.getDynamitePerTrip())
		{
			setCurrentAction(new HelperAction(
				HelperAction.Kind.DEPOSIT_SACK,
				"Deposit ore into the sack",
				List.of(NortheastSite.SACK),
				DEPOSIT_COLOR));
			return;
		}

		if (dynamite == 0)
		{
			HelperAction pendingLight = pendingLightAction(bySite, dynamite);
			if (pendingLight != null)
			{
				setCurrentAction(pendingLight);
				return;
			}

			if (guidePickup && groundOreTracker.hasAnyOre())
			{
				setCurrentAction(new HelperAction(
					HelperAction.Kind.COLLECT_ORE,
					"Pick up remaining ore",
					groundOreTracker.allOreTiles(),
					DEPOSIT_COLOR));
				return;
			}
			if (oreCount > 0)
			{
				setCurrentAction(new HelperAction(
					HelperAction.Kind.DEPOSIT_SACK,
					"Deposit ore (" + oreCount + ")",
					List.of(NortheastSite.SACK),
					DEPOSIT_COLOR));
				return;
			}
			if (blastThenLoot)
			{
				tripExhausted = true;
			}
			setCurrentAction(bankDynamiteAction(inv, "Use noted dynamite on the bank chest"));
			return;
		}

		HelperAction prep = prepInventoryAction(inv, plan, oreCount == 0 && groundClear);
		if (prep != null)
		{
			setCurrentAction(prep);
			return;
		}

		if (dynamite <= config.lowDynamiteThreshold() && oreCount == 0 && groundClear)
		{
			setCurrentAction(bankDynamiteAction(inv, "Low dynamite (" + dynamite + ") — refill at the chest"));
			return;
		}

		boolean allowPickup = !blastThenLoot
			&& HelperPolicy.emitCollectAtPair(config.rotationMethod(), guidePickup)
			&& (shortFinale
				? blastedThisTrip.containsAll(plan.finaleSites())
				: blastedThisTrip.containsAll(NortheastSite.ORDER));

		for (NortheastSite site : sites)
		{
			if (completedThisPass.contains(site))
			{
				continue;
			}

			List<BlastMineRock> siteRocks = bySite.getOrDefault(site, Collections.emptyList());
			HelperAction action = actionForSite(site, siteRocks, shortFinale && !blastThenLoot, allowPickup, dynamite);
			if (action != null)
			{
				setCurrentAction(action);
				return;
			}
		}

		NortheastSite waiting = firstIncompleteSite(sites);
		if (waiting != null)
		{
			setCurrentAction(new HelperAction(
				HelperAction.Kind.IDLE,
				"Waiting for pair " + waiting.getLabel() + " to respawn",
				waiting.getWallTiles(),
				NEXT_COLOR));
			return;
		}

		setCurrentAction(new HelperAction(
			HelperAction.Kind.IDLE,
			blastThenLoot
				? "Ready — blast every pair, then loot"
				: shortFinale
					? "Finale done — pick up and deposit"
					: "Ready — start at pair 1-2",
			shortFinale && !blastThenLoot
				? highlightForFinale(plan)
				: NortheastSite.PAIR_1_2.getWallTiles(),
			NEXT_COLOR));
	}

	private List<NortheastSite> activeSites(TripPlan plan, boolean blastThenLoot)
	{
		if (blastThenLoot)
		{
			return NortheastSite.ORDER;
		}
		if (!shortFinale)
		{
			return NortheastSite.ORDER;
		}

		List<NortheastSite> finale = new ArrayList<>(plan.finaleSites());
		NortheastSite leftover = plan.leftoverSite();
		if (leftover != null && !finale.contains(leftover))
		{
			finale.add(leftover);
		}
		return finale;
	}

	private static List<WorldPoint> highlightForFinale(TripPlan plan)
	{
		List<WorldPoint> tiles = new ArrayList<>();
		for (NortheastSite site : plan.finaleSites())
		{
			tiles.add(site.getTile());
		}
		return tiles.isEmpty() ? NortheastSite.PAIR_1_2.getWallTiles() : tiles;
	}

	private void setCurrentAction(HelperAction action)
	{
		HelperAction next = action != null ? action : HelperAction.idle();
		if (next.equals(currentAction))
		{
			return;
		}
		currentAction = next;
		List<WorldPoint> tiles = next.getHighlightTiles();
		if (tiles == null || tiles.isEmpty())
		{
			focusTiles = Collections.emptySet();
		}
		else
		{
			focusTiles = Collections.unmodifiableSet(new HashSet<>(tiles));
		}
	}

	private HelperAction bankDynamiteAction(InventorySnapshot inv, String detail)
	{
		if (!inv.isNotedDynamite())
		{
			detail = "Need noted dynamite — use it on the bank chest";
		}
		return new HelperAction(
			HelperAction.Kind.BANK_DYNAMITE,
			detail,
			List.of(NortheastSite.BANK_CHEST),
			WARN_COLOR);
	}

	/**
	 * Require chisel, tinderbox, noted dynamite, auto-sized placeholders, and trip-size
	 * empty/unnoted slots before starting. Placeholders are 28 − dynamite − tools so the
	 * chest fill matches the trip.
	 */
	private HelperAction prepInventoryAction(InventorySnapshot inv, TripPlan plan, boolean fullKitRequired)
	{
		int placeholders = plan.placeholderSlots();
		int tripSize = plan.getDynamitePerTrip();
		List<String> missing = new ArrayList<>();
		if (!inv.isChisel())
		{
			missing.add("chisel");
		}
		if (!inv.isTinderbox())
		{
			missing.add("tinderbox");
		}

		if (!fullKitRequired && missing.isEmpty())
		{
			return null;
		}

		if (fullKitRequired)
		{
			if (!inv.isNotedDynamite())
			{
				missing.add("noted dynamite");
			}
			if (inv.getPlaceholderItems() < placeholders)
			{
				missing.add((placeholders - inv.getPlaceholderItems()) + " more filler item(s)");
			}
			if (inv.oreCycleCapacity() < tripSize)
			{
				missing.add(tripSize + " empty slots or unnoted dynamite");
			}
		}

		if (missing.isEmpty())
		{
			return null;
		}

		WorldPoint highlight = (!inv.isNotedDynamite() || inv.oreCycleCapacity() < tripSize)
			? NortheastSite.BANK_CHEST
			: NortheastSite.PAIR_1_2.getTile();

		return new HelperAction(
			HelperAction.Kind.PREP_INVENTORY,
			"Need " + String.join(", ", missing),
			List.of(highlight),
			WARN_COLOR);
	}

	private InventorySnapshot scanInventory()
	{
		boolean chisel = false;
		boolean tinderbox = false;
		boolean notedDynamite = false;
		int emptySlots = 0;
		int placeholderItems = 0;

		ItemContainer inventory = client.getItemContainer(InventoryID.INV);
		if (inventory == null)
		{
			return new InventorySnapshot(false, false, false, 0, INVENTORY_SIZE, 0);
		}

		Item[] items = inventory.getItems();
		for (int i = 0; i < INVENTORY_SIZE; i++)
		{
			Item item = i < items.length ? items[i] : null;
			if (item == null || item.getId() < 0)
			{
				emptySlots++;
				continue;
			}

			int id = item.getId();
			if (id == ItemID.CHISEL)
			{
				chisel = true;
				continue;
			}
			if (id == ItemID.TINDERBOX)
			{
				tinderbox = true;
				continue;
			}
			if (id == ItemID.LOVAKENGJ_DYNAMITE_FUSED)
			{
				continue;
			}

			ItemComposition def = client.getItemDefinition(id);
			if (def.getNote() != -1 && def.getLinkedNoteId() == ItemID.LOVAKENGJ_DYNAMITE_FUSED)
			{
				notedDynamite = true;
				continue;
			}

			placeholderItems++;
		}

		return new InventorySnapshot(
			chisel,
			tinderbox,
			notedDynamite,
			inventory.count(ItemID.LOVAKENGJ_DYNAMITE_FUSED),
			emptySlots,
			placeholderItems);
	}

	private NortheastSite firstIncompleteSite(List<NortheastSite> sites)
	{
		for (NortheastSite site : sites)
		{
			if (!completedThisPass.contains(site))
			{
				return site;
			}
		}
		return null;
	}

	private HelperAction pendingLightAction(Map<NortheastSite, List<BlastMineRock>> bySite, int dynamite)
	{
		for (NortheastSite site : NortheastSite.ORDER)
		{
			List<BlastMineRock> siteRocks = bySite.getOrDefault(site, Collections.emptyList());
			List<BlastMineRock> loaded = filter(siteRocks, BlastMineRockType.LOADED);
			List<BlastMineRock> lit = filter(siteRocks, BlastMineRockType.LIT);

			if (!HelperPolicy.canLightLoadedPots(dynamite, loaded.size(), lit.size()))
			{
				continue;
			}

			String detail = loaded.size() >= 2
				? "Light pair " + site.getLabel()
				: "Light leftover pot on " + site.getLabel();
			return new HelperAction(
				HelperAction.Kind.LIGHT,
				detail,
				tilesOf(loaded, site),
				WARN_COLOR);
		}
		return null;
	}

	private void updatePassProgress(
		List<NortheastSite> sites,
		Map<NortheastSite, List<BlastMineRock>> bySite,
		TripPlan plan,
		boolean blastThenLoot)
	{
		for (NortheastSite site : sites)
		{
			List<BlastMineRock> siteRocks = bySite.getOrDefault(site, Collections.emptyList());
			if (needsBlastingWork(siteRocks))
			{
				workedThisPass.add(site);
			}
			if (workedThisPass.contains(site)
				&& hasBeenFired(siteRocks)
				&& !needsBlastingWork(siteRocks))
			{
				completedThisPass.add(site);
				blastedThisTrip.add(site);
			}
		}

		boolean allDone = !sites.isEmpty();
		for (NortheastSite site : sites)
		{
			if (!completedThisPass.contains(site))
			{
				allDone = false;
				break;
			}
		}
		if (allDone)
		{
			completedThisPass.clear();
			workedThisPass.clear();
			if (!blastThenLoot && !shortFinale)
			{
				fullPassesCompleted++;
				if (fullPassesCompleted >= plan.getFullLaps())
				{
					shortFinale = true;
				}
			}
		}
	}

	private HelperAction actionForSite(
		NortheastSite site,
		List<BlastMineRock> siteRocks,
		boolean finale,
		boolean allowPickup,
		int dynamite)
	{
		List<BlastMineRock> normal = filter(siteRocks, BlastMineRockType.NORMAL);
		List<BlastMineRock> chiseled = filter(siteRocks, BlastMineRockType.CHISELED);
		List<BlastMineRock> loaded = filter(siteRocks, BlastMineRockType.LOADED);
		List<BlastMineRock> lit = filter(siteRocks, BlastMineRockType.LIT);

		String finalePrefix = finale ? "Finale — " : "";

		if (allowPickup && groundOreTracker.hasOreAtSite(site)
			&& chiseled.isEmpty() && loaded.isEmpty() && lit.isEmpty())
		{
			List<WorldPoint> oreTiles = groundOreTracker.oreTilesForSite(site);
			if (oreTiles.isEmpty())
			{
				oreTiles = List.of(site.getTile());
			}
			return new HelperAction(
				HelperAction.Kind.COLLECT_ORE,
				finalePrefix + "Pick up ore at " + site.getLabel(),
				oreTiles,
				DEPOSIT_COLOR);
		}

		if (siteRocks.isEmpty())
		{
			return new HelperAction(
				HelperAction.Kind.EXCAVATE,
				finalePrefix + "Excavate pair " + site.getLabel(),
				site.getWallTiles(),
				NEXT_COLOR);
		}

		if (!normal.isEmpty())
		{
			return new HelperAction(
				HelperAction.Kind.EXCAVATE,
				finalePrefix + "Excavate pair " + site.getLabel(),
				tilesOf(normal, site),
				NEXT_COLOR);
		}

		if (!chiseled.isEmpty())
		{
			return new HelperAction(
				HelperAction.Kind.PLACE_DYNAMITE,
				finalePrefix + "Place dynamite on " + site.getLabel(),
				tilesOf(chiseled, site),
				NEXT_COLOR);
		}

		if (HelperPolicy.canLightLoadedPots(dynamite, loaded.size(), lit.size()))
		{
			return new HelperAction(
				HelperAction.Kind.LIGHT,
				loaded.size() >= 2
					? finalePrefix + "Light pair " + site.getLabel()
					: finalePrefix + "Light leftover pot on " + site.getLabel(),
				tilesOf(loaded, site),
				loaded.size() == 1 ? WARN_COLOR : NEXT_COLOR);
		}

		if (loaded.size() == 1)
		{
			return new HelperAction(
				HelperAction.Kind.PLACE_DYNAMITE,
				finalePrefix + "Load the other pot on " + site.getLabel(),
				site.getWallTiles(),
				WARN_COLOR);
		}

		return null;
	}

	private static boolean needsBlastingWork(List<BlastMineRock> siteRocks)
	{
		for (BlastMineRock rock : siteRocks)
		{
			BlastMineRockType type = rock.getType();
			if (type == BlastMineRockType.NORMAL
				|| type == BlastMineRockType.CHISELED
				|| type == BlastMineRockType.LOADED)
			{
				return true;
			}
		}
		return false;
	}

	private static boolean hasBeenFired(List<BlastMineRock> siteRocks)
	{
		for (BlastMineRock rock : siteRocks)
		{
			if (rock.getType() == BlastMineRockType.LIT)
			{
				return true;
			}
		}
		return false;
	}

	private Map<NortheastSite, List<BlastMineRock>> groupBySite(Map<WorldPoint, BlastMineRock> rocks)
	{
		Map<NortheastSite, List<BlastMineRock>> map = new EnumMap<>(NortheastSite.class);
		for (NortheastSite site : NortheastSite.values())
		{
			map.put(site, new ArrayList<>());
		}

		for (BlastMineRock rock : rocks.values())
		{
			NortheastSite site = NortheastSite.forWallTile(rock.getGameObject().getWorldLocation());
			if (site != null)
			{
				map.get(site).add(rock);
			}
		}
		return map;
	}

	private static List<BlastMineRock> filter(List<BlastMineRock> rocks, BlastMineRockType type)
	{
		List<BlastMineRock> out = new ArrayList<>();
		for (BlastMineRock rock : rocks)
		{
			if (rock.getType() == type)
			{
				out.add(rock);
			}
		}
		return out;
	}

	private static List<WorldPoint> tilesOf(List<BlastMineRock> rocks, NortheastSite site)
	{
		List<WorldPoint> tiles = new ArrayList<>();
		for (BlastMineRock rock : rocks)
		{
			WorldPoint point = rock.getGameObject().getWorldLocation();
			if (site.isWallTile(point) && !tiles.contains(point))
			{
				tiles.add(point);
			}
		}
		if (tiles.isEmpty())
		{
			return site.getWallTiles();
		}
		return tiles;
	}

	private void refreshSackCache()
	{
		cachedSackFull = computeSackFull();
		cachedTotalSackOres = computeTotalSackOres();
		cachedSackXp = computeSackXp();
	}

	public boolean isSackFull()
	{
		return cachedSackFull;
	}

	public int estimateSackXp()
	{
		return cachedSackXp;
	}

	public int totalSackOres()
	{
		return cachedTotalSackOres;
	}

	private boolean computeSackFull()
	{
		return client.getVarbitValue(VarbitID.LOVAKENGJ_ORE_COAL_BIGGER) >= SACK_FULL_THRESHOLD
			|| client.getVarbitValue(VarbitID.LOVAKENGJ_ORE_GOLD_BIGGER) >= SACK_FULL_THRESHOLD
			|| client.getVarbitValue(VarbitID.LOVAKENGJ_ORE_MITHRIL_BIGGER) >= SACK_FULL_THRESHOLD
			|| client.getVarbitValue(VarbitID.LOVAKENGJ_ORE_ADAMANTITE_BIGGER) >= SACK_FULL_THRESHOLD
			|| client.getVarbitValue(VarbitID.LOVAKENGJ_ORE_RUNITE_BIGGER) >= SACK_FULL_THRESHOLD;
	}

	private int computeSackXp()
	{
		int coal = client.getVarbitValue(VarbitID.LOVAKENGJ_ORE_COAL_BIGGER);
		int gold = client.getVarbitValue(VarbitID.LOVAKENGJ_ORE_GOLD_BIGGER);
		int mith = client.getVarbitValue(VarbitID.LOVAKENGJ_ORE_MITHRIL_BIGGER);
		int addy = client.getVarbitValue(VarbitID.LOVAKENGJ_ORE_ADAMANTITE_BIGGER);
		int rune = client.getVarbitValue(VarbitID.LOVAKENGJ_ORE_RUNITE_BIGGER);

		double xp = coal * 33.0
			+ gold * 66.0
			+ mith * 120.0
			+ addy * 190.0
			+ rune * 260.0;

		if (config.requireProspectors())
		{
			xp *= 1.025;
		}
		return (int) Math.round(xp);
	}

	/** True when the "require prospectors" setting is on and the player isn't wearing the full kit. */
	public boolean needsProspectorKit()
	{
		return config.requireProspectors() && !hasFullProspectorKit();
	}

	private boolean hasFullProspectorKit()
	{
		ItemContainer equipment = client.getItemContainer(InventoryID.WORN);
		if (equipment == null)
		{
			return false;
		}
		return isWorn(equipment, EquipmentInventorySlot.HEAD, PROSPECTOR_HELMS)
			&& isWorn(equipment, EquipmentInventorySlot.BODY, PROSPECTOR_BODIES)
			&& isWorn(equipment, EquipmentInventorySlot.LEGS, PROSPECTOR_LEGS)
			&& isWorn(equipment, EquipmentInventorySlot.BOOTS, PROSPECTOR_BOOTS);
	}

	private static boolean isWorn(ItemContainer equipment, EquipmentInventorySlot slot, int[] itemIds)
	{
		Item item = equipment.getItem(slot.getSlotIdx());
		if (item == null)
		{
			return false;
		}
		for (int itemId : itemIds)
		{
			if (item.getId() == itemId)
			{
				return true;
			}
		}
		return false;
	}

	private int computeTotalSackOres()
	{
		return client.getVarbitValue(VarbitID.LOVAKENGJ_ORE_COAL_BIGGER)
			+ client.getVarbitValue(VarbitID.LOVAKENGJ_ORE_GOLD_BIGGER)
			+ client.getVarbitValue(VarbitID.LOVAKENGJ_ORE_MITHRIL_BIGGER)
			+ client.getVarbitValue(VarbitID.LOVAKENGJ_ORE_ADAMANTITE_BIGGER)
			+ client.getVarbitValue(VarbitID.LOVAKENGJ_ORE_RUNITE_BIGGER);
	}
}

package com.blastmineimproved;

import java.util.Collections;
import java.util.List;

/**
 * How a trip of {@code n} dynamite maps onto NE pairs: full 1-2→7-8 laps, then a short
 * finale of leftover even pairs, then an optional odd last pot.
 *
 * <p>20 dynamite is 2 laps + pairs 1-2 and 3-4. 21 is the same plus one leftover pot.
 * 16 is exactly 2 laps with no finale.
 */
final class TripPlan
{
	private static final int PAIRS_PER_LAP = 8;
	private static final int INVENTORY_SIZE = 28;
	/** Chisel, tinderbox, and a noted dynamite stack — the kit the chest fill is sized around. */
	private static final int TOOL_SLOTS = 3;

	private final int dynamitePerTrip;
	private final int fullLaps;
	private final int finalePairCount;
	private final boolean oddLeftover;

	private TripPlan(int dynamitePerTrip, int fullLaps, int finalePairCount, boolean oddLeftover)
	{
		this.dynamitePerTrip = dynamitePerTrip;
		this.fullLaps = fullLaps;
		this.finalePairCount = finalePairCount;
		this.oddLeftover = oddLeftover;
	}

	static TripPlan of(int dynamitePerTrip)
	{
		int n = Math.max(0, dynamitePerTrip);
		int fullLaps = n / PAIRS_PER_LAP;
		int remainder = n % PAIRS_PER_LAP;
		return new TripPlan(n, fullLaps, remainder / 2, remainder % 2 == 1);
	}

	int getDynamitePerTrip()
	{
		return dynamitePerTrip;
	}

	/**
	 * Filler slots so using noted dynamite on the chest yields exactly {@link #getDynamitePerTrip()}.
	 * 20 dynamite → 5 placeholders; 21 → 4.
	 */
	int placeholderSlots()
	{
		return Math.max(0, INVENTORY_SIZE - dynamitePerTrip - TOOL_SLOTS);
	}

	int getFullLaps()
	{
		return fullLaps;
	}

	int getFinalePairCount()
	{
		return finalePairCount;
	}

	boolean hasOddLeftover()
	{
		return oddLeftover;
	}

	List<NortheastSite> finaleSites()
	{
		int count = Math.min(finalePairCount, NortheastSite.ORDER.size());
		if (count <= 0)
		{
			return Collections.emptyList();
		}
		return NortheastSite.ORDER.subList(0, count);
	}

	/**
	 * After the even finale pairs, the next site in order holds the leftover single pot
	 * (21 dynamite → pair 5-6 after 1-2 and 3-4).
	 */
	NortheastSite leftoverSite()
	{
		if (!oddLeftover)
		{
			return null;
		}
		int index = Math.min(finalePairCount, NortheastSite.ORDER.size() - 1);
		return NortheastSite.ORDER.get(index);
	}
}

package com.blastmineimproved;

import com.google.common.collect.ImmutableMap;
import java.util.Map;
import lombok.Getter;
import net.runelite.api.gameval.ObjectID;

public enum BlastMineRockType
{
	NORMAL(ObjectID.BLAST_MINING_WALL_01, ObjectID.BLAST_MINING_WALL_02),
	CHISELED(ObjectID.BLAST_MINING_WALL_CHISELED_01, ObjectID.BLAST_MINING_WALL_CHISELED_02),
	LOADED(ObjectID.BLAST_MINING_WALL_POT_01, ObjectID.BLAST_MINING_WALL_POT_02),
	LIT(ObjectID.BLAST_MINING_WALL_BURNING_01, ObjectID.BLAST_MINING_WALL_BURNING_02),
	EXPLODED(ObjectID.BLAST_MINING_WALL_DESTROYED_01, ObjectID.BLAST_MINING_WALL_DESTROYED_02);

	private static final Map<Integer, BlastMineRockType> ROCK_TYPES;

	static
	{
		ImmutableMap.Builder<Integer, BlastMineRockType> builder = new ImmutableMap.Builder<>();
		for (BlastMineRockType type : values())
		{
			for (int spotId : type.getObjectIds())
			{
				builder.put(spotId, type);
			}
		}
		ROCK_TYPES = builder.build();
	}

	@Getter
	private final int[] objectIds;

	BlastMineRockType(int... objectIds)
	{
		this.objectIds = objectIds;
	}

	public static BlastMineRockType getRockType(int objectId)
	{
		return ROCK_TYPES.get(objectId);
	}
}

package com.blastmineimproved;

import net.runelite.api.Client;
