final class BlastMineArea
{
	/** Lovakengj Blast Mine. Shared with {@link NortheastSite} markers. */
	static final int REGION_ID = 5948;

	private BlastMineArea()
	{
	}

	static boolean isInBlastMine(Client client)
	{
