package com.blastmineimproved;

import java.awt.Color;
import java.util.List;
import lombok.Getter;
import lombok.Value;
import net.runelite.api.coords.WorldPoint;

@Value
public class HelperAction
{
	/**
	 * Policy lives on the kind so icons, menu strip, and left-click prefer cannot drift.
	 * Icon hide and menu strip are separate: COLLECT_ORE hides rock icons but must not
	 * strip Light (that was the 21st-dynamite bug).
	 */
	public enum Kind
	{
		IDLE("Idle", false, false, false),
		EXCAVATE("Excavate", true, true, true, "Excavate"),
		PLACE_DYNAMITE("Place dynamite", true, true, true, "Place", "Use"),
		LIGHT("Light", true, true, true, "Light"),
		COLLECT_ORE("Collect ore", true, false, false, "Take", "Pick-up"),
		DEPOSIT_SACK("Deposit sack", true, false, false, "Deposit"),
		BANK_DYNAMITE("Bank dynamite", true, false, false, "Use"),
		PREP_INVENTORY("Prepare inventory", true, false, false, "Use", "Deposit"),
		COLLECT_OPERATOR("Visit operator", true, false, false, "Talk-to", "Collect"),
		WEAR_PROSPECTORS("Wear prospectors", true, false, false, "Talk-to", "Collect");

		@Getter
		private final String label;
		private final boolean hideOffPathIcons;
		private final boolean iconsOnFocusOnly;
		private final boolean stripOffPathRockMenus;
		private final String[] preferOptions;

		Kind(String label, boolean hideOffPathIcons, boolean iconsOnFocusOnly, boolean stripOffPathRockMenus, String... preferOptions)
		{
			this.label = label;
			this.hideOffPathIcons = hideOffPathIcons;
			this.iconsOnFocusOnly = iconsOnFocusOnly;
			this.stripOffPathRockMenus = stripOffPathRockMenus;
			this.preferOptions = preferOptions;
		}

		public boolean hidesOffPathIcons()
		{
			return hideOffPathIcons;
		}

		public boolean iconsOnFocusOnly()
		{
			return iconsOnFocusOnly;
		}

		public boolean stripsOffPathRockMenus()
		{
			return stripOffPathRockMenus;
		}

		public boolean matchesPrefer(String option)
		{
			if (option == null)
			{
				return false;
			}
			for (String prefer : preferOptions)
			{
				if (prefer.equals(option))
				{
					return true;
				}
			}
			return this == DEPOSIT_SACK && option.contains("Deposit");
		}
	}

	Kind kind;
	String detail;
	List<WorldPoint> highlightTiles;
	Color color;

	public static HelperAction idle()
	{
		return new HelperAction(Kind.IDLE, "Waiting…", List.of(), Color.GRAY);
	}
}

package com.blastmineimproved;

import java.time.Duration;
import java.time.Instant;
import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.Deque;
import java.util.HashMap;
import java.util.Iterator;
import java.util.List;
import java.util.Map;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.api.gameval.InventoryID;
import net.runelite.api.gameval.ItemID;

/**
 * Tracks the 3-minute disintegration timer of blasted ore held in the inventory.
 *
 * <p>The lifetime starts when the ore spawns on the ground, so pickup times are seeded from
 * {@link GroundOreTracker} rather than the moment the ore enters the inventory. Timers are keyed
 * by inventory slot and reassigned when ore is moved between slots.
 */
@Singleton
public class BlastedOreTracker
{
	public static final Duration ORE_LIFETIME = Duration.ofMinutes(3);
	private static final int INVENTORY_SIZE = 28;

	public static final class OreTimer
	{
		private final Instant spawnedAt;

		OreTimer(Instant spawnedAt)
		{
			this.spawnedAt = spawnedAt;
		}

		public Duration remaining()
		{
			Duration left = ORE_LIFETIME.minus(Duration.between(spawnedAt, Instant.now()));
			return left.isNegative() ? Duration.ZERO : left;
		}

		public double remainingRelative()
		{
			return remaining().toMillis() / (double) ORE_LIFETIME.toMillis();
		}
	}

	private final Client client;

	/** Inventory slot index -> ground spawn time of the ore currently in that slot. */
	private final Map<Integer, Instant> timersBySlot = new HashMap<>();

	/** Ground spawn times of ore that left the ground this tick (pickup candidates). */
	private final Deque<Instant> pendingPickups = new ArrayDeque<>();

	@Inject
	BlastedOreTracker(Client client)
	{
		this.client = client;
	}

	public void reset()
	{
		timersBySlot.clear();
		pendingPickups.clear();
	}

	/**
	 * Record that blasted ore left the ground this tick, carrying its original spawn time so the
	 * timer that follows it into the inventory reflects floor time already elapsed.
	 */
	public void onGroundOrePickedUp(Instant spawnedAt, int quantity)
	{
		Instant time = spawnedAt != null ? spawnedAt : Instant.now();
		for (int i = 0; i < quantity; i++)
		{
			pendingPickups.addLast(time);
		}
	}

	public void syncFromInventory()
	{
		ItemContainer inventory = client.getItemContainer(InventoryID.INV);
		if (inventory == null)
		{
			timersBySlot.clear();
			pendingPickups.clear();
			return;
		}

		final Item[] items = inventory.getItems();
		final int limit = Math.min(items.length, INVENTORY_SIZE);

		final boolean[] isOreSlot = new boolean[INVENTORY_SIZE];
		for (int slot = 0; slot < limit; slot++)
		{
			Item item = items[slot];
			isOreSlot[slot] = item != null && item.getId() == ItemID.LOVAKENGJ_BLASTED_ORE;
		}

		// Free timers from slots that no longer hold ore (deposited, disintegrated, or moved out).
		final List<Instant> freedTimers = new ArrayList<>();
		for (Iterator<Map.Entry<Integer, Instant>> it = timersBySlot.entrySet().iterator(); it.hasNext(); )
		{
			Map.Entry<Integer, Instant> entry = it.next();
			int slot = entry.getKey();
			if (slot >= INVENTORY_SIZE || !isOreSlot[slot])
			{
				freedTimers.add(entry.getValue());
				it.remove();
			}
		}

		// Slots that now hold ore but have no timer yet (picked up or moved in).
		final List<Integer> gainedSlots = new ArrayList<>();
		for (int slot = 0; slot < limit; slot++)
		{
			if (isOreSlot[slot] && !timersBySlot.containsKey(slot))
			{
				gainedSlots.add(slot);
			}
		}

		if (!gainedSlots.isEmpty())
		{
			// Assign moved-ore times first (oldest first), then fresh ground pickups from this tick.
			freedTimers.sort(Comparator.naturalOrder());
			final Deque<Instant> available = new ArrayDeque<>(freedTimers);
			available.addAll(pendingPickups);

			for (int slot : gainedSlots)
			{
				Instant time = available.pollFirst();
				timersBySlot.put(slot, time != null ? time : Instant.now());
			}
		}

		// Pending pickups are only valid for the tick in which the ground ore despawned.
		pendingPickups.clear();
	}

	public OreTimer timerForSlot(int slot)
	{
		Instant spawnedAt = timersBySlot.get(slot);
		return spawnedAt != null ? new OreTimer(spawnedAt) : null;
	}

	public int getOreCount()
	{
		return timersBySlot.size();
	}
}

package com.blastmineimproved;

import java.time.Duration;
import java.time.Instant;
import lombok.Getter;
import net.runelite.api.GameObject;

@Getter
public class BlastMineRock
{
	private static final Duration PLANT_TIME = Duration.ofSeconds(30);
	private static final Duration FUSE_TIME = Duration.ofMillis(4200);

	private final GameObject gameObject;
	private final BlastMineRockType type;
	private final Instant creationTime = Instant.now();

	BlastMineRock(final GameObject gameObject, BlastMineRockType blastMineRockType)
	{
		this.gameObject = gameObject;
		this.type = blastMineRockType;
	}

	public double getRemainingFuseTimeRelative()
	{
		Duration duration = Duration.between(creationTime, Instant.now());
		return duration.compareTo(FUSE_TIME) < 0
			? (double) duration.toMillis() / FUSE_TIME.toMillis()
			: 1;
	}

	public double getRemainingTimeRelative()
	{
		Duration duration = Duration.between(creationTime, Instant.now());
		return duration.compareTo(PLANT_TIME) < 0
			? (double) duration.toMillis() / PLANT_TIME.toMillis()
			: 1;
	}
}

package com.blastmineimproved;

import java.time.Instant;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.Getter;
import net.runelite.api.TileItem;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.gameval.ItemID;

/**
 * Tracks blasted ore sitting on the ground (picked up on the next pass, or when dynamite is gone).
 *
 * <p>Also records when each pile first spawned so the inventory disintegration timer can start from
 * ground-spawn time rather than pickup time; on pickup the spawn time is handed to
 * {@link BlastedOreTracker}.
 */
@Singleton
public class GroundOreTracker
{
	@Getter
	private final Map<WorldPoint, Integer> oreByTile = new HashMap<>();

	/** Oldest ground-spawn time still present on each tile. */
	private final Map<WorldPoint, Instant> spawnedAt = new HashMap<>();

	private final BlastedOreTracker blastedOreTracker;

	@Inject
	GroundOreTracker(BlastedOreTracker blastedOreTracker)
	{
		this.blastedOreTracker = blastedOreTracker;
	}

	public void reset()
	{
		oreByTile.clear();
		spawnedAt.clear();
	}

	public void onItemSpawned(WorldPoint point, TileItem item)
	{
		if (item == null || item.getId() != ItemID.LOVAKENGJ_BLASTED_ORE)
		{
			return;
		}
		oreByTile.merge(point, Math.max(1, item.getQuantity()), Integer::sum);
		spawnedAt.putIfAbsent(point, Instant.now());
	}

	public void onItemDespawned(WorldPoint point, TileItem item)
	{
		if (item == null || item.getId() != ItemID.LOVAKENGJ_BLASTED_ORE)
		{
			return;
		}
		int qty = Math.max(1, item.getQuantity());
		Integer remaining = oreByTile.get(point);
		if (remaining == null)
		{
			return;
		}
		int removed = Math.min(qty, remaining);
		blastedOreTracker.onGroundOrePickedUp(spawnedAt.get(point), removed);
		if (remaining <= qty)
		{
			oreByTile.remove(point);
			spawnedAt.remove(point);
		}
		else
		{
			oreByTile.put(point, remaining - qty);
		}
	}

	public void onItemQuantityChanged(WorldPoint point, TileItem item, int oldQuantity)
	{
		if (item == null || item.getId() != ItemID.LOVAKENGJ_BLASTED_ORE)
		{
			return;
		}
		int delta = item.getQuantity() - oldQuantity;
		if (delta > 0)
		{
			oreByTile.merge(point, delta, Integer::sum);
			spawnedAt.putIfAbsent(point, Instant.now());
		}
		else if (delta < 0)
		{
			Integer remaining = oreByTile.get(point);
			if (remaining == null)
			{
				return;
			}
			int removed = Math.min(-delta, remaining);
			blastedOreTracker.onGroundOrePickedUp(spawnedAt.get(point), removed);
			int next = remaining + delta;
			if (next <= 0)
			{
				oreByTile.remove(point);
				spawnedAt.remove(point);
			}
			else
			{
				oreByTile.put(point, next);
			}
		}
	}

	/**
	 * Assign each ore pile to the single nearest pair site so adjacent pairs
	 * (e.g. 1-2 and 3-4) do not share highlights.
	 */
	public NortheastSite ownerSite(WorldPoint oreTile)
	{
		NortheastSite best = null;
		int bestDistance = Integer.MAX_VALUE;
		for (NortheastSite site : NortheastSite.values())
		{
			int distance = distanceToSite(oreTile, site);
			if (distance < bestDistance)
			{
				bestDistance = distance;
				best = site;
			}
		}
		// Ore further than 1 tile from marker/walls likely isn't from that blast
		return bestDistance <= 1 ? best : null;
	}

	private static int distanceToSite(WorldPoint oreTile, NortheastSite site)
	{
		return Math.min(
			oreTile.distanceTo(site.getTile()),
			Math.min(oreTile.distanceTo(site.getWallA()), oreTile.distanceTo(site.getWallB())));
	}

	public boolean hasOreAtSite(NortheastSite site)
	{
		return !oreTilesForSite(site).isEmpty();
	}

	public boolean hasAnyOre()
	{
		return !oreByTile.isEmpty();
	}

	public List<WorldPoint> allOreTiles()
	{
		return new ArrayList<>(oreByTile.keySet());
	}

	public List<WorldPoint> oreTilesForSite(NortheastSite site)
	{
		List<WorldPoint> tiles = new ArrayList<>();
		for (WorldPoint oreTile : oreByTile.keySet())
		{
			if (ownerSite(oreTile) == site)
			{
				tiles.add(oreTile);
			}
		}
		return tiles;
	}
}

package com.blastmineimproved;

import java.util.Map;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.GameObject;
import net.runelite.api.ItemContainer;
import net.runelite.api.MenuEntry;
import net.runelite.api.NPC;
import net.runelite.api.Tile;
import net.runelite.api.coords.LocalPoint;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.events.MenuEntryAdded;
import net.runelite.api.gameval.InventoryID;
import net.runelite.api.gameval.ItemID;
import net.runelite.api.gameval.ObjectID;

@Singleton
public class MenuSafetyService
{
	private static final String EXCAVATE = "Excavate";
	private static final String LIGHT = "Light";
	private static final String PLACE = "Place";
	private static final String COLLECT = "Collect";
	private static final String OPERATOR_NPC_NAME = "Operator";

	private final Client client;
	private final BlastMineImprovedConfig config;
	private final HelperService helperService;

	@Inject
	MenuSafetyService(Client client, BlastMineImprovedConfig config, HelperService helperService)
	{
		this.client = client;
		this.config = config;
		this.helperService = helperService;
	}

	public void onMenuEntryAdded(MenuEntryAdded event, Map<WorldPoint, BlastMineRock> rocks)
	{
		if (!BlastMineArea.isInBlastMine(client))
		{
			return;
		}

		String option = event.getOption();
		MenuEntry entry = event.getMenuEntry();
		boolean outOfDynamite = !hasUnnotedDynamite();

		if (config.deprioritizeWithoutDynamite()
			&& EXCAVATE.equals(option)
			&& isHardRock(event.getIdentifier())
			&& outOfDynamite)
		{
			entry.setDeprioritized(true);
		}

		if (config.enableHelper() && config.hideOffPathMenus() && helperService.isFocusingBlastingStep())
		{
			if (EXCAVATE.equals(option) || PLACE.equals(option) || LIGHT.equals(option))
			{
				// Loaded pots must stay firable when dynamite is gone (odd last pot).
				if (LIGHT.equals(option) && HelperPolicy.neverRemoveLight(outOfDynamite ? 0 : 1))
				{
					// keep Light
				}
				else
				{
					WorldPoint point = worldPointForMenuTarget(entry);
					if (point != null && !helperService.isFocusTile(point))
					{
						client.getMenu().removeMenuEntry(entry);
						return;
					}
				}
			}
		}

		if (COLLECT.equals(option) && helperService.needsProspectorKit() && isOperator(entry))
		{
			client.getMenu().removeMenuEntry(entry);
			return;
		}

		if (config.pairLightSafety()
			&& LIGHT.equals(option)
			&& isLoadedPot(event.getIdentifier())
			&& !HelperPolicy.neverRemoveLight(outOfDynamite ? 0 : 1))
		{
			WorldPoint point = worldPointForMenuTarget(entry);
			if (point != null && !bothPotsLoaded(point, rocks))
			{
				client.getMenu().removeMenuEntry(entry);
				return;
			}
		}

		if (config.prioritizeHelperOptions())
		{
			preferHelperOption(entry, option);
		}
	}

	private void preferHelperOption(MenuEntry entry, String option)
	{
		HelperAction action = helperService.getCurrentAction();
		if (action == null || action.getKind() == HelperAction.Kind.IDLE)
		{
			return;
		}

		if (!action.getKind().matchesPrefer(option))
		{
			return;
		}

		WorldPoint point = worldPointForMenuTarget(entry);
		if (point != null && !action.getHighlightTiles().isEmpty() && !helperService.isFocusTile(point))
		{
			return;
		}

		entry.setForceLeftClick(true);
	}

	/**
	 * Allow Light when both cavities are ready: each is LOADED or already LIT.
	 * Hides Light until the partner pot is placed; keeps Light available on the
	 * second pot after the first has been lit.
	 */
	private boolean bothPotsLoaded(WorldPoint point, Map<WorldPoint, BlastMineRock> rocks)
	{
		NortheastSite site = NortheastSite.forWallTile(point);
		if (site == null)
		{
			site = NortheastSite.nearestTo(point);
		}
		if (site == null)
		{
			return true;
		}

		return isLoadedOrLitAt(site.getWallA(), rocks) && isLoadedOrLitAt(site.getWallB(), rocks);
	}

	private boolean isLoadedOrLitAt(WorldPoint wall, Map<WorldPoint, BlastMineRock> rocks)
	{
		BlastMineRock tracked = rocks.get(wall);
		if (tracked != null
			&& (tracked.getType() == BlastMineRockType.LOADED || tracked.getType() == BlastMineRockType.LIT))
		{
			return true;
		}

		for (Map.Entry<WorldPoint, BlastMineRock> entry : rocks.entrySet())
		{
			BlastMineRockType type = entry.getValue().getType();
			if (type != BlastMineRockType.LOADED && type != BlastMineRockType.LIT)
			{
				continue;
			}
			WorldPoint loc = entry.getKey();
			if (wall.equals(loc) || wall.distanceTo(loc) == 0)
			{
				return true;
			}
		}

		return sceneHasLoadedOrLitPot(wall);
	}

	private boolean sceneHasLoadedOrLitPot(WorldPoint wall)
	{
		LocalPoint local = LocalPoint.fromWorld(client, wall);
		if (local == null)
		{
			return false;
		}

		Tile[][][] tiles = client.getScene().getTiles();
		int plane = client.getPlane();
		int x = local.getSceneX();
		int y = local.getSceneY();
		if (x < 0 || y < 0 || plane < 0 || plane >= tiles.length
			|| x >= tiles[plane].length || y >= tiles[plane][x].length)
		{
			return false;
		}

		Tile tile = tiles[plane][x][y];
		if (tile == null)
		{
			return false;
		}

		GameObject[] objects = tile.getGameObjects();
		if (objects != null)
		{
			for (GameObject go : objects)
			{
				if (go != null && (isLoadedPot(go.getId()) || isLitPot(go.getId())))
				{
					return true;
				}
			}
		}

		return false;
	}

	private static boolean isOperator(MenuEntry entry)
	{
		NPC npc = entry.getNpc();
		return npc != null && OPERATOR_NPC_NAME.equals(npc.getName());
	}

	private WorldPoint worldPointForMenuTarget(MenuEntry entry)
	{
		return WorldPoint.fromScene(client, entry.getParam0(), entry.getParam1(), client.getPlane());
	}

	private boolean hasUnnotedDynamite()
	{
		ItemContainer inventory = client.getItemContainer(InventoryID.INV);
		return inventory != null && inventory.contains(ItemID.LOVAKENGJ_DYNAMITE_FUSED);
	}

	private static boolean isHardRock(int id)
	{
		return id == ObjectID.BLAST_MINING_WALL_01 || id == ObjectID.BLAST_MINING_WALL_02;
	}

	private static boolean isLoadedPot(int id)
	{
		return id == ObjectID.BLAST_MINING_WALL_POT_01 || id == ObjectID.BLAST_MINING_WALL_POT_02;
	}

	private static boolean isLitPot(int id)
	{
		return id == ObjectID.BLAST_MINING_WALL_BURNING_01 || id == ObjectID.BLAST_MINING_WALL_BURNING_02;
	}
}

